input.content:
import { Frontmatter } from './markdown';

export interface Page {
  slug: string;
  title: string;
  date: string | null;
  tags: string[];
  html: string;
  rendered: string;
  template: string | null;
  layout: string | null;
  frontmatter: Frontmatter;
  sourcePath: string;
  outputPath: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  plugins?: Plugin[];
}

export interface BuildResult {
  pages: Page[];
  outputDir: string;
  indexPath: string;
}

export interface Plugin {
  name?: string;
  onStart?(): void;
  beforeBuild?(): void;
  afterBuild?(): void;
  onFile?(page: Page): void;
  onEnd?(): void;
}

import * as path from 'path';
import { Page } from './plugin';
import { RenderContext } from './templates';

export function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function relativeIndexLink(outputPath: string): string {
  const dir = path.dirname(outputPath);
  const rel = path.relative(dir, 'index.html');
  return rel.split(path.sep).join('/');
}

export function renderMeta(date: string | null, tags: string[]): string {
  const meta: string[] = [];
  if (date) {
    meta.push(
      `<time datetime="${escapeHtml(date)}">${escapeHtml(date)}</time>`
    );
  }
  if (tags.length > 0) {
    meta.push(
      `<ul class="tags">${tags
        .map((tag) => `<li>${escapeHtml(tag)}</li>`)
        .join('')}</ul>`
    );
  }
  return meta.join('\n');
}

export function pageContext(page: Page): RenderContext {
  return {
    ...page.frontmatter,
    title: page.title,
    date: page.date,
    tags: page.tags,
    content: page.html,
    slug: page.slug,
    sourcePath: page.sourcePath,
    outputPath: page.outputPath,
    home: relativeIndexLink(page.outputPath),
    meta: renderMeta(page.date, page.tags),
  };
}

export function renderIndex(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const date = page.date
        ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(
            page.date
          )}</time>`
        : '';
      const tags = page.tags.length
        ? ` <span class="tags">${page.tags
            .map((tag) => escapeHtml(tag))
            .join(', ')}</span>`
        : '';
      return `<li><a href="${escapeHtml(page.outputPath)}">${escapeHtml(
        page.title
      )}</a>${date}${tags}</li>`;
    })
    .join('\n');

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Index</title>
</head>
<body>
<h1>Index</h1>
<ul>
${items}
</ul>
</body>
</html>
`;
}

import * as fs from 'fs';
import { parseMarkdown } from '../markdown';
import { Page, Plugin } from '../plugin';

function normalizeDate(value: unknown): string | null {
  if (value === null || value === undefined) {
    return null;
  }
  if (value instanceof Date) {
    return value.toISOString().slice(0, 10);
  }
  const str = String(value).trim();
  return str.length > 0 ? str : null;
}

function normalizeTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map((v) => String(v).trim()).filter((v) => v.length > 0);
  }
  if (typeof value === 'string') {
    return value
      .split(',')
      .map((v) => v.trim())
      .filter((v) => v.length > 0);
  }
  return [];
}

function normalizeName(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null;
  }
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  onFile(page: Page): void {
    const raw = fs.readFileSync(page.sourcePath, 'utf8');
    const { frontmatter, html } = parseMarkdown(raw);

    const rawTitle = frontmatter.title;
    const title =
      typeof rawTitle === 'string' && rawTitle.trim().length > 0
        ? rawTitle.trim()
        : page.slug;

    page.frontmatter = frontmatter;
    page.html = html;
    page.title = title;
    page.date = normalizeDate(frontmatter.date);
    page.tags = normalizeTags(frontmatter.tags);
    page.template = normalizeName(frontmatter.template);
    page.layout = normalizeName(frontmatter.layout);
  }
}

import { TemplateEngine } from '../templates';
import { Page, Plugin } from '../plugin';
import { pageContext } from '../render';

export class TemplatePlugin implements Plugin {
  name = 'templates';

  private readonly engine: TemplateEngine;

  constructor(templatesDir: string) {
    this.engine = new TemplateEngine(templatesDir);
  }

  onFile(page: Page): void {
    page.rendered = this.engine.render(
      page.template,
      page.layout,
      pageContext(page)
    );
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { Page, Plugin, BuildResult } from './plugin';
import { renderIndex } from './render';

export interface EngineOptions {
  contentDir: string;
  outputDir: string;
}

type LifecycleHook = 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd';

function collectMarkdownFiles(dir: string): string[] {
  const results: string[] = [];
  if (!fs.existsSync(dir)) {
    return results;
  }
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...collectMarkdownFiles(full));
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
      results.push(full);
    }
  }
  return results;
}

function toSlug(contentDir: string, filePath: string): string {
  const rel = path.relative(contentDir, filePath);
  const ext = path.extname(rel);
  const withoutExt = ext ? rel.slice(0, -ext.length) : rel;
  return withoutExt.split(path.sep).join('/');
}

export class Engine {
  private readonly options: EngineOptions;
  private readonly plugins: Plugin[];

  constructor(options: EngineOptions, plugins: Plugin[]) {
    this.options = options;
    this.plugins = plugins;
  }

  build(): BuildResult {
    const { contentDir, outputDir } = this.options;

    this.emit('onStart');
    this.emit('beforeBuild');

    const files = collectMarkdownFiles(contentDir);
    const pages: Page[] = files.map((file) => {
      const slug = toSlug(contentDir, file);
      const page: Page = {
        slug,
        title: '',
        date: null,
        tags: [],
        html: '',
        rendered: '',
        template: null,
        layout: null,
        frontmatter: {},
        sourcePath: file,
        outputPath: `${slug}.html`,
      };
      for (const plugin of this.plugins) {
        plugin.onFile?.(page);
      }
      return page;
    });

    pages.sort((a, b) => {
      const aDate = a.date;
      const bDate = b.date;
      if (!aDate && !bDate) {
        return a.title.localeCompare(b.title);
      }
      if (!aDate) {
        return 1;
      }
      if (!bDate) {
        return -1;
      }
      return bDate.localeCompare(aDate);
    });

    fs.mkdirSync(outputDir, { recursive: true });

    for (const page of pages) {
      const outFile = path.join(outputDir, page.outputPath);
      fs.mkdirSync(path.dirname(outFile), { recursive: true });
      fs.writeFileSync(outFile, page.rendered);
    }

    const indexPath = path.join(outputDir, 'index.html');
    fs.writeFileSync(indexPath, renderIndex(pages));

    this.emit('afterBuild');
    this.emit('onEnd');

    return { pages, outputDir, indexPath };
  }

  private emit(hook: LifecycleHook): void {
    for (const plugin of this.plugins) {
      plugin[hook]?.();
    }
  }
}

import * as path from 'path';
import { BuildOptions, BuildResult, Page, Plugin } from './plugin';
import { Engine } from './engine';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/templates';

export { Page, BuildOptions, BuildResult } from './plugin';
export { escapeHtml } from './render';

export function build(options: BuildOptions): BuildResult {
  const templatesDir = options.templatesDir ?? path.resolve('templates');
  const plugins: Plugin[] = [new MarkdownPlugin(), new TemplatePlugin(templatesDir)];
  if (options.plugins) {
    plugins.push(...options.plugins);
  }

  const engine = new Engine(
    { contentDir: options.contentDir, outputDir: options.outputDir },
    plugins
  );

  return engine.build();
}

import * as fs from 'fs';
import * as http from 'http';
import * as net from 'net';
import * as path from 'path';
import chokidar from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { build } from '../builder';
import { Plugin } from '../plugin';

export interface ServeOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  port: number;
  host?: string;
}

export interface DevServer {
  port: number;
  host: string;
  outputDir: string;
  server: http.Server;
  close(): Promise<void>;
}

export const LIVE_RELOAD_PATH = '/__ssg_live_reload';

const LIVE_RELOAD_SCRIPT = `<script>
(function () {
  var protocol = location.protocol === 'https:' ? 'wss://' : 'ws://';
  var socket = new WebSocket(protocol + location.host + '${LIVE_RELOAD_PATH}');
  socket.onmessage = function (event) {
    if (event.data === 'reload') {
      location.reload();
    }
  };
})();
</script>
`;

export function injectLiveReloadScript(html: string): string {
  const bodyClose = html.lastIndexOf('</body>');
  if (bodyClose !== -1) {
    return (
      html.slice(0, bodyClose) + LIVE_RELOAD_SCRIPT + html.slice(bodyClose)
    );
  }
  return html + LIVE_RELOAD_SCRIPT;
}

const CONTENT_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.webp': 'image/webp',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.txt': 'text/plain; charset=utf-8',
  '.md': 'text/plain; charset=utf-8',
};

function contentTypeFor(filePath: string): string {
  return CONTENT_TYPES[path.extname(filePath).toLowerCase()] ?? 'application/octet-stream';
}

function isInside(baseDir: string, target: string): boolean {
  const rel = path.relative(path.resolve(baseDir), target);
  return rel !== '' && !rel.startsWith('..') && !path.isAbsolute(rel);
}

export function createDevServer(options: ServeOptions): DevServer {
  const contentDir = path.resolve(options.contentDir);
  const outputDir = path.resolve(options.outputDir);
  const templatesDir = options.templatesDir ?? path.resolve('templates');
  const host = options.host ?? '127.0.0.1';
  const port = options.port;

  const rebuild = (): void => {
    const result = build({
      contentDir,
      outputDir,
      templatesDir,
    });
    process.stdout.write(
      `Rebuilt ${result.pages.length} page(s) to ${result.outputDir}\n`
    );
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  };

  const server = http.createServer((req, res) => {
    const requestUrl = (req.url ?? '/').split('?')[0];
    let decoded: string;
    try {
      decoded = decodeURIComponent(requestUrl);
    } catch {
      res.writeHead(400);
      res.end('Bad Request');
      return;
    }
    let filePath = path.join(outputDir, decoded === '/' ? 'index.html' : decoded);
    filePath = path.normalize(filePath);

    if (!isInside(outputDir, filePath)) {
      res.writeHead(403);
      res.end('Forbidden');
      return;
    }

    if (fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
      const isHtml = path.extname(filePath).toLowerCase() === '.html';
      let body = fs.readFileSync(filePath);
      if (isHtml) {
        body = Buffer.from(injectLiveReloadScript(body.toString('utf8')));
      }
      res.writeHead(200, {
        'Content-Type': contentTypeFor(filePath),
        'Content-Length': body.length,
      });
      res.end(body);
      return;
    }

    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Not Found');
  });

  const wss = new WebSocketServer({ noServer: true });

  const connections = new Set<net.Socket>();
  server.on('connection', (socket) => {
    connections.add(socket);
    socket.on('close', () => {
      connections.delete(socket);
    });
  });

  server.on('upgrade', (req, socket, head) => {
    const requestUrl = (req.url ?? '').split('?')[0];
    if (requestUrl !== LIVE_RELOAD_PATH) {
      socket.destroy();
      return;
    }
    wss.handleUpgrade(req, socket, head, (ws) => {
      wss.emit('connection', ws, req);
    });
  });

  rebuild();

  const watchPaths = [contentDir, templatesDir].filter((dir) =>
    fs.existsSync(dir)
  );

  const watcher = chokidar.watch(watchPaths, {
    ignoreInitial: true,
    persistent: false,
    awaitWriteFinish: { stabilityThreshold: 100, pollInterval: 20 },
  });

  let watcherReady = watchPaths.length === 0;
  watcher.on('ready', () => {
    watcherReady = true;
  });

  let rebuildTimer: NodeJS.Timeout | null = null;
  const scheduleRebuild = (): void => {
    if (rebuildTimer) {
      clearTimeout(rebuildTimer);
    }
    rebuildTimer = setTimeout(() => {
      rebuildTimer = null;
      try {
        rebuild();
      } catch (err) {
        process.stderr.write(`Rebuild failed: ${String(err)}\n`);
      }
    }, 50);
  };

  watcher.on('add', scheduleRebuild);
  watcher.on('change', scheduleRebuild);
  watcher.on('unlink', scheduleRebuild);

  server.listen(port, host);

  return {
    port,
    host,
    outputDir,
    server,
    close: async () => {
      if (rebuildTimer) {
        clearTimeout(rebuildTimer);
        rebuildTimer = null;
      }
      if (!watcherReady) {
        await new Promise<void>((resolve) => {
          const timer = setTimeout(resolve, 1000);
          watcher.once('ready', () => {
            clearTimeout(timer);
            resolve();
          });
        });
      }
      await watcher.close();
      for (const client of wss.clients) {
        client.terminate();
      }
      await new Promise<void>((resolve) => wss.close(() => resolve()));
      for (const socket of connections) {
        socket.destroy();
      }
      await new Promise<void>((resolve) => {
        server.close(() => resolve());
        server.closeAllConnections?.();
      });
      await new Promise<void>((resolve) => setTimeout(resolve, 0));
    },
  };
}

export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  private readonly options: ServeOptions;
  private devServer: DevServer | null = null;

  constructor(options: ServeOptions) {
    this.options = options;
  }

  onStart(): void {
    this.devServer = createDevServer(this.options);
  }

  onEnd(): void {
    if (this.devServer) {
      void this.devServer.close();
    }
  }

  start(): DevServer {
    this.devServer = createDevServer(this.options);
    return this.devServer;
  }
}

import { createDevServer, ServeOptions, DevServer } from './plugins/server';

export {
  ServeOptions,
  DevServer,
  LIVE_RELOAD_PATH,
  injectLiveReloadScript,
  DevServerPlugin,
} from './plugins/server';

export function startServer(options: ServeOptions): DevServer {
  return createDevServer(options);
}

import * as fs from 'fs';
import * as path from 'path';
import { Plugin } from './plugin';

export interface SsgConfig {
  plugins?: Plugin[];
}

export function loadConfig(configPath = 'ssg.config.ts'): SsgConfig {
  const resolved = path.resolve(configPath);
  if (!fs.existsSync(resolved)) {
    return {};
  }

  const source = fs.readFileSync(resolved, 'utf8');
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const ts = require('typescript') as typeof import('typescript');
  const js = ts.transpileModule(source, {
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2020,
      esModuleInterop: true,
    },
  }).outputText;

  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const Module: any = require('module');
  const mod = new Module(resolved);
  mod.filename = resolved;
  mod.paths = Module._nodeModulePaths(path.dirname(resolved));
  mod._compile(js, resolved);

  const exported = mod.exports as Record<string, unknown>;
  const config = (exported && 'default' in exported
    ? exported.default
    : exported) as SsgConfig;

  return config ?? {};
}

